head.script:
scwin.screenId = "jldfil05031";

///////// 1. 변수 및 선언 영역 /////////

// as-is 공용 상수 — 셸이 js/elw.js 를 싣지 않아 화면에 선언한다(KRX 합의 대상).
scwin.SELECT = 2;

scwin.form = null;


///////// 2. 초기화 영역 /////////

// 조건 평가 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_conds
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_conds = async function () {
    const binds = [{ id: "btn_ElwPreDataDownload", fn: function(){ return ((dma_readDataVO.get("listBzTpCd") ?? (() => { throw new Error("unresolved:" + "readDataVO.listBzTpCd"); })()) === '002'); } }];
    let applied = 0;
    for (let i = 0; i < binds.length; i++) {
        const b = binds[i];
        try {
            const ok = !!b.fn();
            const comp = $c.util.getComponent(b.id);
            if (comp && comp.setStyle) { comp.setStyle("display", ok ? "" : "none"); }
            else if (comp) { if (ok) { if (comp.show) { comp.show(); } } else if (comp.hide) { comp.hide(); } }
            if (ok && b.grids) {
                for (let gi = 0; gi < b.grids.length; gi++) {
                    const gc = $c.util.getComponent(b.grids[gi]);
                    if (gc && gc.refreshGridView) { gc.refreshGridView(); }
                }
            }
            applied++;
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); }
    }
    return applied;
};

// dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_rowCopy
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_rowCopy = async function () {
    const rows = [{ childId: "__rb0", fn: function () { return "전체 " + String(dma_page.get("total")) + "건 (" + String(dma_page.get("currentPage")) + "/" + String(dma_page.get("pageCount")) + " 페이지) "; } }];
    let copied = 0;
    for (let i = 0; i < rows.length; i++) {
        const it = rows[i];
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { console.warn("[sdd] 행 복사 대상 부재: " + it.childId); continue; }
        try {
            const v = it.fn();
            if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); copied++; }
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); }
    }
    return copied;
};

/**
 * @method
 * @name scwin.init_pageBody
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_pageBody = function () {
    try {
        /* sdd-asis-lifecycle:begin onpageload — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        scwin.form = (document.prelistPageForm || { elements: [] });
        $c.util.getComponent("dma_ElwMstReq").set("bzCd", BZ_USRLST);
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil05031.onpageload' }); }
};

// [A] 초기 목록 미해결 — 자기 목록을 채우는 tx 가 2개다(tx_fn_ElwMst, tx_fn_ElwPreDataDownload) — 어느 것이 «열자마자» 인지 정할 근거가 없다


// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { console.warn("[sdd] 전환 파라미터 수신 대상 없음: dma_pageContext — 읽는 자리 0"); };

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_rowCopy();
        await scwin.init_conds();
        scwin.init_pageBody();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldfil05031.onpageload' });
    }
};


///////// 3. 컴포넌트 이벤트 영역 /////////

/**
 * @event
 * @name scwin.btn_Search_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.btn_Search_onclick = async function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin btn_Search_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        await scwin.search()
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil05031.btn_Search_onclick' }); }
};

/**
 * @event
 * @name scwin.slc_currentPageSize_onchange
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.slc_currentPageSize_onchange = async function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin slc_currentPageSize_onchange — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        await scwin.search();
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil05031.slc_currentPageSize_onchange' }); }
};

/**
 * @event
 * @name scwin.grd_pageList_oncellclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param rowIndex columnIndex columnId
 * @returns
 * @hidden N
*/
scwin.grd_pageList_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_pageList');
        if (!dl) { console.error('[sdd] 행 동작 대상 목록 없음: dlt_pageList'); return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; }
        if (typeof scwin.elwMst === 'function') { await scwin.elwMst(r["isuCd"], r["bzProcsNo"], r["listBzTpCd"]); } else { console.error('[sdd] 행 동작 미정의: scwin.elwMst (열 ?)'); await $c.win.alert('이 행 동작을 아직 정하지 못했습니다(전환 미완) — scwin.elwMst'); } return;
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_pageList.oncellclick' });
    }
};

/**
 * @event
 * @name scwin.btn_ElwPreDataDownload_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.btn_ElwPreDataDownload_onclick = async function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin btn_ElwPreDataDownload_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        await scwin.elwPreDataDownload()
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil05031.btn_ElwPreDataDownload_onclick' }); }
};


///////// 4. 서브미션 콜백 영역 /////////

/**
 * @method
 * @name scwin.tx_fn_ElwMst
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fn_ElwMst = async function () {
    const sbmOptions = {
        id: "tx_fn_ElwMst",
        method: "post",
        action: "/list/elw.do",
        ref: "dma_ElwMstReq",
        target: "dlt_pageList=body.content",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldfil05031.tx_fn_ElwMst" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};

/**
 * @method
 * @name scwin.tx_fn_ElwPreDataDownload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fn_ElwPreDataDownload = async function () {
    const sbmOptions = {
        id: "tx_fn_ElwPreDataDownload",
        method: "post",
        action: "/list/elw.do",
        ref: "dma_ElwPreDataDownloadReq",
        target: "dlt_pageList=body.content",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldfil05031.tx_fn_ElwPreDataDownload" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};


///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.elwMst
 * @author Inswave
 * @date 2026. 09. 29
 * @param isuCd bzProcsNo listBzTpCd
 * @returns
 * @hidden N
*/
scwin.elwMst = async function (isuCd, bzProcsNo, listBzTpCd) {
    /* sdd-asis-lifecycle:begin fn_ElwMst — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $c.util.getComponent("dma_ElwMstReq").set("transKind", scwin.SELECT);
    $c.util.getComponent('dma_ElwMstReq').set('isuCd', isuCd);
    $c.util.getComponent('dma_ElwMstReq').set('bzProcsNo', bzProcsNo);
    $c.util.getComponent("slc_listBzTpCd").setValue(listBzTpCd);
    fn_clearTransTbl();
    fn_setBzCd();
    fn_setMainPage();
    scwin.form.action = '/list/elw.do';
    $c.util.getComponent('dma_ElwMstReq').set('method', 'searchElw');
    await scwin.tx_fn_ElwMst();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.search
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.search = async function () {
    /* sdd-asis-lifecycle:begin fn_Search — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $c.util.getComponent('dma_ElwMstReq').set('method', 'elwPageSearch');
    await moveUrl('/list/elw.do', {});
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.elwPreDataDownload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.elwPreDataDownload = async function () {
    /* sdd-asis-lifecycle:begin fn_ElwPreDataDownload — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (await $c.win.confirm("검색기간(" + $c.util.getComponent('cal_listBzApplDdTm1').getValue()+ " ~ " + $c.util.getComponent('cal_listBzApplDdTm2').getValue()+ ") 내에 신청한\n『상장예비심사청구』내역을 전체 다운로드합니다.")) {
        scwin.form.action = '/list/elw.do';
        $c.util.getComponent('dma_ElwMstReq').set('method', 'elwPreDataDownload');
        await scwin.tx_fn_ElwPreDataDownload();
    } else {
        return;
    }
    /* sdd-asis-lifecycle:end */
};



/**
 * @event
 * @name scwin.krxpage_pagenavigator_111_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param index
 * @returns
 * @hidden N
*/
scwin.krxpage_pagenavigator_111_onclick = function (index) { const pi = (index && typeof index === 'object') ? index.newSelectedIndex : index; try { $c.util.getComponent('dma_ElwMstReq').set('pageIndex', pi); } catch (e) { $c.exception.handleError(e, { notify: 'none', context: 'krxpage_pagenavigator_111.page' }); } scwin.search(); };
